// Generate migrations/006_settings.sql from content/settings.seed.json.
//   node scripts/build-settings-migration.mjs
// One source, so planning/01-SETTINGS.md, the seed file and the database cannot drift.
import { readFileSync, writeFileSync } from 'node:fs';
const src = JSON.parse(readFileSync(new URL('../content/settings.seed.json', import.meta.url), 'utf8'));
const q = (s) => "'" + String(s).replaceAll("'", "''") + "'";
const rows = Object.entries(src).filter(([k]) => !k.startsWith('_'));
const out = [
  '-- Scoop Dogg - seed every setting.',
  '--',
  '-- GENERATED by scripts/build-settings-migration.mjs from content/settings.seed.json.',
  '-- Do not hand-edit; regenerate. After seeding, the DATABASE is the source of truth and',
  '-- Josue edits these in the admin - this file is only the starting position.',
  '--',
  '-- Every default is sourced, most from promises his own site already makes, so if he',
  '-- never opens the settings screen the business runs on what he has publicly committed to.',
  '',
  'begin;',
  '',
];
for (const [key, { v, why }] of rows) {
  out.push(`-- ${why}`);
  out.push(`insert into settings (key, value, updated_by) values (${q(key)}, ${q(JSON.stringify(v))}::jsonb, 'seed')`);
  out.push(`  on conflict (key) do nothing;`);
}
out.push('', `do $$ declare n int; begin`, `  select count(*) into n from settings;`,
  `  if n <> ${rows.length} then raise exception 'expected ${rows.length} settings, found %', n; end if;`,
  `end $$;`, '', 'commit;', '');
writeFileSync(new URL('../migrations/006_settings.sql', import.meta.url), out.join('\n'));
console.log(`wrote 006_settings.sql — ${rows.length} settings`);
